Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -29,4 +29,26 @@
 <div id="screen"><div class="card"><div class="eyebrow">ONE TINY ARENA. BIG ENERGY.</div><h1>JETPACK <span>RUMBLE</span></h1><p class="sub" id="intro">Suit up, take the high ground, and outfly the squad. A fast little arena shooter built for one more round.</p><div class="features"><span class="tag"><b>01</b> QUICK MATCH</span><span class="tag"><b>✦</b> JETPACK COMBAT</span><span class="tag"><b>∞</b> RESPAWNS</span></div><button class="play" id="play">DROP INTO THE ARENA&nbsp; ↗</button><div class="foot"><span><i class="key">A</i> <i class="key">D</i> MOVE &nbsp; <i class="key">SPACE</i> BOOST</span><span>MOUSE AIM + FIRE</span></div></div></div>
 <div id="mobile"><div class="cluster"><button class="touchbtn" data-control="left">◀</button><button class="touchbtn" data-control="right">▶</button></div><div class="cluster"><button class="touchbtn" data-control="jump">▲</button><button class="touchbtn big" data-control="fire">FIRE</button></div></div>
 </div>
 <script>
+(()=>{
+const canvas=document.querySelector('#c'),ctx=canvas.getContext('2d');
+const ui={screen:document.querySelector('#screen'),top:document.querySelector('#topbar'),hud:document.querySelector('#bottom-hud'),mobile:document.querySelector('#mobile'),play:document.querySelector('#play'),score:document.querySelector('#score'),clock:document.querySelector('#clock'),best:document.querySelector('#best'),health:document.querySelector('#healthBar'),healthNum:document.querySelector('#healthNum'),fuel:document.querySelector('#fuelBar'),fuelNum:document.querySelector('#fuelNum'),ammo:document.querySelector('#ammo'),toast:document.querySelector('#toast'),intro:document.querySelector('#intro')};
+let W=innerWidth,H=innerHeight,DPR=1,scale=1,cam={x:0,y:0},last=0,elapsed=0,remaining=90,active=false,ended=false,score=0,toastTimer=0;
+const world={w:2600,h:980,ground:850};
+const platforms=[{x:0,y:850,w:2600,h:130,type:'ground'},{x:210,y:680,w:300,h:24},{x:610,y:560,w:280,h:24},{x:1000,y:700,w:370,h:24},{x:1460,y:575,w:280,h:24},{x:1870,y:685,w:350,h:24},{x:2280,y:540,w:220,h:24},{x:400,y:420,w:240,h:22},{x:1110,y:420,w:300,h:22},{x:1740,y:390,w:300,h:22},{x:880,y:285,w:190,h:20},{x:1510,y:260,w:220,h:20}];
+let player,bots=[],bullets=[],sparks=[],pickups=[],keys={},pointer={x:W*.7,y:H*.5,down:false},touch={left:false,right:false,jump:false,fire:false},ammo=24,reserve=96,reload=0,spawnTimer=0,shake=0;
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';scale=Math.min(W/1280,H/720);ctx.setTransform(DPR,0,0,DPR,0,0)}
+addEventListener('resize',resize);resize();
+function makeSoldier(x,y,isPlayer=false){return{x,y,w:34,h:48,vx:0,vy:0,health:100,fuel:100,face:1,grounded:false,shootCd:0,invuln:0,dead:false,respawn:0,bot:!isPlayer,ai:rand(0,2),color:isPlayer?'#d9ff63':['#ff785f','#78a9ff','#ffc45c','#d78cff'][Math.floor(rand(0,4))],name:isPlayer?'YOU':['ROOK','NOVA','ACE','KITE'][Math.floor(rand(0,4))]}}
+function reset(){elapsed=0;remaining=90;score=0;ammo=24;reserve=96;reload=0;bullets=[];sparks=[];pickups=[];player=makeSoldier(260,world.ground-48,true);bots=[];for(let i=0;i<4;i++)bots.push(makeSoldier(rand(800,2350),world.ground-48));spawnTimer=8;ended=false;updateHud()}
+function start(){reset();active=true;ui.screen.classList.add('hidden');ui.top.classList.add('active');ui.hud.classList.add('active');ui.mobile.classList.toggle('show',matchMedia('(pointer:coarse)').matches);last=performance.now();requestAnimationFrame(loop)}
+ui.play.addEventListener('click',start);
+addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR'&&active)beginReload();if(e.code==='Escape'&&active){active=false;ui.screen.classList.remove('hidden');ui.top.classList.remove('active');ui.hud.classList.remove('active');ui.mobile.classList.remove('show');ui.play.textContent='RESUME THE RUMBLE  ↗';ui.intro.textContent='The arena is holding its breath. Ready to jump back in?'}});addEventListener('keyup',e=>keys[e.code]=false);
+canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY});canvas.addEventListener('pointerdown',e=>{pointer.down=true;canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointerup',()=>pointer.down=false);canvas.addEventListener('pointercancel',()=>pointer.down=false);
+document.querySelectorAll('.touchbtn').forEach(b=>{const c=b.dataset.control;const set=(v,e)=>{e.preventDefault();touch[c]=v;b.classList.toggle('on',v)};b.addEventListener('pointerdown',e=>set(true,e));b.addEventListener('pointerup',e=>set(false,e));b.addEventListener('pointercancel',e=>set(false,e));b.addEventListener('pointerleave',e=>{if(e.buttons===0)set(false,e)})});
+function beginReload(){if(reload<=0&&ammo<24&&reserve>0){reload=1.05;notify('RELOADING…')}}
+function notify(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=1.2}
+function screenToWorld(sx,sy){return{x:(sx-W/2)/scale+cam.x+W/(2*scale),y:(sy-H/2)/scale+cam.y+H/(2*scale)}}
+function fire(owner,targetX,targetY){if(owner.dead||owner.shootCd>0)return;if(owner===player){if(reload>0)return;if(ammo<=0){beginReload();return}ammo--;updateHud()}const cx=owner.x+owner.w/2,cy=owner.y+owner.h*.45,dx=targetX-cx,dy=targetY-cy,len=Math.hypot(dx,dy)||1,spd=owner===player?790:490;bullets.push({x:cx+dx/len*22,y:cy+dy/len*22,vx:dx/len*spd,vy:dy/len*spd,life:owner===player?1.5:2,owner,color:owner===player?'#eaff91':'#ff9678',damage:owner===player?25:12});owner.shootCd=owner===player?.16:rand(.8,1.4);if(owner===player)shake=.8}
+function updateHud(){ui.score.textContent=String(score).padStart(2,'0');ui.best.textContent=String(Math.max(score,Number(localStorage.getItem('skyBest')||0))).padStart(2,'0');ui.clock.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(Math.ceil(remaining%60)).padStart(2,'0')}`;ui.health.style.width=clamp(player?.health||0,0,100)+'%';ui.healthNum.textContent=Math.ceil(player?.health||0)+'%';ui.fuel.style.width=clamp(player?.fuel||0,0,100)+'%';ui.fuelNum.textContent=Math.ceil(player?.fuel||0)+'%';ui.ammo.innerHTML=`${String(ammo).padStart(2,'0')} <em>/ ${reserve}</em>`}

