function updateHud(){ui.score.textContent=String(score).padStart(2,'0');ui.best.textContent=String(Math.max(score,Number(localStorage.getItem('skyBest')||0))).padStart(2,'0');ui.clock.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(Math.ceil(remaining%60)).padStart(2,'0')}`;ui.health.style.width=clamp(player?.health||0,0,100)+'%';ui.healthNum.textContent=Math.ceil(player?.health||0)+'%';ui.fuel.style.width=clamp(player?.fuel||0,0,100)+'%';ui.fuelNum.textContent=Math.ceil(player?.fuel||0)+'%';ui.ammo.innerHTML=`${String(ammo).padStart(2,'0')} <em>/ ${reserve}</em>`}
function physics(a,dt){if(a.dead){a.respawn-=dt;if(a.respawn<=0){a.dead=false;a.health=100;a.fuel=100;a.x=a===player?rand(140,world.w-140):rand(300,world.w-200);a.y=world.ground-50;a.vx=0;a.vy=0;a.invuln=2}return}
const oldY=a.y; a.vy+=1500*dt;a.x+=a.vx*dt;a.y+=a.vy*dt;a.vx*=Math.pow(a.grounded?.80:.985,dt*60);a.grounded=false;
for(const p of platforms){if(a.vy>=0&&oldY+a.h<=p.y+3&&a.y+a.h>=p.y&&a.x+a.w>p.x&&a.x<p.x+p.w){a.y=p.y-a.h;a.vy=0;a.grounded=true}}
if(a.x<0){a.x=0;a.vx=Math.max(0,a.vx)}if(a.x+a.w>world.w){a.x=world.w-a.w;a.vx=Math.min(0,a.vx)}if(a.y>world.h+100){a.health=0;kill(a,null)}a.shootCd=Math.max(0,a.shootCd-dt);a.invuln=Math.max(0,a.invuln-dt);
}
function hurt(a,amount,from){if(a.dead||a.invuln>0)return;a.health-=amount;sparks.push({x:a.x+a.w/2,y:a.y+a.h/2,life:.25,color:'#fff2a1'});if(a.health<=0)kill(a,from)}
function kill(a,from){if(a.dead)return;a.dead=true;a.respawn=2.2;a.vy=-220;for(let i=0;i<12;i++)sparks.push({x:a.x+a.w/2,y:a.y+a.h/2,vx:rand(-230,230),vy:rand(-280,120),life:rand(.3,.8),color:a.color});if(a===player){notify('SUIT DOWN · BACK IN 2');}else if(from===player){score++;localStorage.setItem('skyBest',Math.max(score,Number(localStorage.getItem('skyBest')||0)));notify('SQUAD ELIMINATED  +1');}updateHud()}
function update(dt){elapsed+=dt;remaining=Math.max(0,90-elapsed);if(remaining===0&&!ended){ended=true;active=false;ui.screen.classList.remove('hidden');ui.play.textContent='RUN IT BACK  ↗';ui.intro.textContent=`Match over — you scored ${score} ${score===1?'elimination':'eliminations'}. Ready for another drop?`;ui.top.classList.remove('active');ui.hud.classList.remove('active');ui.mobile.classList.remove('show')}
if(reload>0){reload-=dt;if(reload<=0){const n=Math.min(24-ammo,reserve);ammo+=n;reserve-=n;updateHud()}}if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.classList.remove('show');
physics(player,dt);let aim=screenToWorld(pointer.x,pointer.y);let movingLeft=keys.KeyA||keys.ArrowLeft||touch.left,movingRight=keys.KeyD||keys.ArrowRight||touch.right,boost=keys.Space||keys.KeyW||keys.ArrowUp||touch.jump;
if(!player.dead){if(movingLeft){player.vx-=1500*dt;player.face=-1}if(movingRight){player.vx+=1500*dt;player.face=1}player.vx=clamp(player.vx,-320,320);if(boost&&player.fuel>0){player.vy-=1900*dt;player.fuel=Math.max(0,player.fuel-34*dt);player.grounded=false;if(Math.random()<dt*28)sparks.push({x:player.x+player.w/2-player.face*4,y:player.y+player.h-2,vx:rand(-40,40),vy:rand(130,320),life:.28,color:Math.random()>.5?'#ffbf63':'#71e6e5'})}else player.fuel=Math.min(100,player.fuel+15*dt);player.face=aim.x>player.x+player.w/2?1:-1;if(pointer.down||touch.fire)fire(player,aim.x,aim.y)}
for(const b of bots){physics(b,dt);if(b.dead)continue;b.ai-=dt;let target=player;if(player.dead||(!Math.random()>.003))target=player; // player remains the squad's main target
if(b.ai<=0){b.ai=rand(.35,1.1);b.wander=rand(-1,1)}let dx=target.x-b.x;b.face=dx>0?1:-1;if(Math.abs(dx)>200)b.vx+=Math.sign(dx)*350*dt;else b.vx*=.98;if(b.grounded&&Math.random()<dt*.55)b.vy=-rand(470,650);if(b.y>target.y+80&&b.grounded)b.vy=-600;b.vx=clamp(b.vx,-210,210);let dy=(target.y+20)-(b.y+20);if(Math.abs(dx)<680&&Math.abs(dy)<390&&Math.random()<dt*1.6)fire(b,target.x+target.w/2+rand(-55,55),target.y+target.h*.45+rand(-70,70));}
for(let i=bullets.length-1;i>=0;i--){let q=bullets[i],ox=q.x,oy=q.y;q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt;let hit=false;for(const p of platforms){if(q.x>p.x&&q.x<p.x+p.w&&q.y>p.y-2&&q.y<p.y+p.h){hit=true;break}}if(!hit){for(const a of [player,...bots]){if(a===q.owner||a.dead||a.invuln>0)continue;if(q.x>a.x-3&&q.x<a.x+a.w+3&&q.y>a.y&&q.y<a.y+a.h){hurt(a,q.damage,q.owner);hit=true;break}}}if(hit||q.life<=0||q.x<0||q.x>world.w)bullets.splice(i,1)}
for(let i=sparks.length-1;i>=0;i--){const s=sparks[i];s.life-=dt;s.x+=(s.vx||0)*dt;s.y+=(s.vy||0)*dt;s.vy=(s.vy||0)+450*dt;if(s.life<=0)sparks.splice(i,1)}
spawnTimer-=dt;if(spawnTimer<=0){spawnTimer=rand(11,17);if(pickups.length<2)pickups.push({x:rand(220,world.w-220),y:rand(300,650),type:Math.random()<.55?'ammo':'health',phase:rand(0,6)})}for(let i=pickups.length-1;i>=0;i--){let p=pickups[i];p.phase+=dt*3;for(const a of [player,...bots]){if(!a.dead&&Math.abs(a.x+a.w/2-p.x)<30&&Math.abs(a.y+a.h/2-(p.y+Math.sin(p.phase)*6))<38){if(a===player){if(p.type==='ammo'){reserve=Math.min(144,reserve+36);notify('AMMO +36')}else{player.health=Math.min(100,player.health+35);notify('VITALS RESTORED')}updateHud()}pickups.splice(i,1);break}}}
cam.x+=(clamp(player.x+player.w/2, W/(2*scale),world.w-W/(2*scale))-cam.x)*Math.min(1,dt*4);cam.y+=(clamp(player.y+player.h/2, H/(2*scale),world.h-H/(2*scale))-cam.y)*Math.min(1,dt*3);shake=Math.max(0,shake-dt*3);if(Math.floor(elapsed*2)!==Math.floor((elapsed-dt)*2))updateHud();}

